148:     /// Evaluates geoid undulation $N(\phi, \lambda)$ in meters using bilinear interpolation.
149:     pub fn interpolate(&self, lat: f64, lon: f64) -> Result<f64> {
150:         if !(-90.0..=90.0).contains(&lat) {
151:             return Err(FlightReaderError::CoordinatesOutOfBounds {
152:                 latitude: lat,
153:                 longitude: lon,
154:             });
155:         }
156: 
157:         // Normalize longitude to [0.0, 360.0)
158:         let mut norm_lon = lon % 360.0;
159:         if norm_lon < 0.0 {
160:             norm_lon += 360.0;
161:         }
162: 
163:         // Compute normalized fractional indices
164:         let x = norm_lon / self.delta_lon;
165:         let y = (90.0 - lat) / self.delta_lat;
166: 
167:         let col0 = x.floor() as usize;
168:         let row0 = y.floor() as usize;
169: 
170:         let col1 = (col0 + 1) % self.width;
171:         let row1 = (row0 + 1).min(self.height - 1);
172: 
173:         let u = x - x.floor();
174:         let v = y - y.floor();
175: 
176:         let n00 = self.get_node_undulation(col0, row0);
177:         let n10 = self.get_node_undulation(col1, row0);
178:         let n01 = self.get_node_undulation(col0, row1);
179:         let n11 = self.get_node_undulation(col1, row1);
180: 
181:         // Bilinear formula: N = (1-u)(1-v)N00 + u(1-v)N10 + (1-u)vN01 + uvN11
182:         let undulation = (1.0 - u) * (1.0 - v) * n00
183:             + u * (1.0 - v) * n10
184:             + (1.0 - u) * v * n01
185:             + u * v * n11;
186: 
187:         Ok(undulation)
188:     }
189: }
